'use strict';

class TodoError extends Error {
  constructor(message) {
    super(message);
    this.name = 'TodoError';
  }
}

const ID_PATTERN = /^\d+$/;

/**
 * Parses a user-supplied todo id. Only plain positive decimal integers are
 * accepted, so inputs like "1.5", "-1", "1e3" or "0x1" are rejected rather
 * than coerced by Number().
 */
function parseId(raw) {
  const trimmed = String(raw).trim();
  const id = Number(trimmed);
  if (!ID_PATTERN.test(trimmed) || !Number.isSafeInteger(id) || id < 1) {
    throw new TodoError(`Invalid todo id "${raw}". Expected a positive integer.`);
  }
  return id;
}

function nextId(todos) {
  return todos.reduce((max, todo) => Math.max(max, todo.id), 0) + 1;
}

/**
 * Returns the trimmed todo text, or throws TodoError if nothing is left.
 */
function parseText(raw) {
  const trimmed = typeof raw === 'string' ? raw.trim() : '';
  if (trimmed === '') {
    throw new TodoError('Todo text cannot be empty.');
  }
  return trimmed;
}

/**
 * Returns a new list with the todo appended; the input list is not mutated.
 */
function addTodo(todos, text, now = new Date()) {
  const todo = {
    id: nextId(todos),
    text: parseText(text),
    completed: false,
    createdAt: now.toISOString(),
  };
  return { todos: [...todos, todo], todo };
}

function findIndex(todos, id) {
  const index = todos.findIndex((todo) => todo.id === id);
  if (index === -1) {
    throw new TodoError(`Todo #${id} not found.`);
  }
  return index;
}

function completeTodo(todos, id) {
  const index = findIndex(todos, id);
  const existing = todos[index];
  if (existing.completed) {
    return { todos, todo: existing, alreadyCompleted: true };
  }
  const todo = { ...existing, completed: true };
  const updated = todos.map((item, i) => (i === index ? todo : item));
  return { todos: updated, todo, alreadyCompleted: false };
}

function deleteTodo(todos, id) {
  const index = findIndex(todos, id);
  return {
    todos: todos.filter((_, i) => i !== index),
    todo: todos[index],
  };
}

function formatTodo(todo) {
  return `${todo.id}. [${todo.completed ? 'x' : ' '}] ${todo.text}`;
}

function formatList(todos) {
  if (todos.length === 0) {
    return 'No todos yet. Add one with: node index.js add "<text>"';
  }
  return todos.map(formatTodo).join('\n');
}

module.exports = {
  TodoError,
  parseId,
  parseText,
  addTodo,
  completeTodo,
  deleteTodo,
  formatList,
};
'use strict';

const { describe, it, beforeEach, afterEach } = require('node:test');
const assert = require('node:assert/strict');
const fs = require('node:fs');
const os = require('node:os');
const path = require('node:path');
const { execFile, spawnSync } = require('node:child_process');
const { promisify } = require('node:util');
const { run } = require('../index');

const ENTRY = path.join(__dirname, '..', 'index.js');
const CHILD_TIMEOUT_MS = 10_000;
// Enough parallel writers to reliably expose a shared temp-file name.
const CONCURRENT_RUNS = 24;

let dir;
let file;

beforeEach(() => {
  dir = fs.mkdtempSync(path.join(os.tmpdir(), 'todo-cli-'));
  file = path.join(dir, 'todos.json');
});

afterEach(() => {
  fs.rmSync(dir, { recursive: true, force: true });
});

function capture() {
  let text = '';
  return { write: (chunk) => { text += chunk; }, get text() { return text; } };
}

function cli(...argv) {
  const stdout = capture();
  const stderr = capture();
  const code = run(argv, { cwd: dir, stdout, stderr });
  return { code, stdout: stdout.text, stderr: stderr.text };
}

function readTodos() {
  return JSON.parse(fs.readFileSync(file, 'utf8'));
}

function assertFails(result, message) {
  assert.equal(result.code, 1);
  assert.equal(result.stdout, '');
  assert.match(result.stderr, message);
}

describe('add', () => {
  it('stores a pending todo with id, text, completed and an ISO createdAt', () => {
    const before = Date.now();
    const result = cli('add', 'Buy groceries');
    assert.deepEqual(result, { code: 0, stdout: 'Added todo #1: Buy groceries\n', stderr: '' });

    const [saved] = readTodos();
    assert.deepEqual(Object.keys(saved).sort(), ['completed', 'createdAt', 'id', 'text']);
    assert.equal(saved.id, 1);
    assert.equal(saved.text, 'Buy groceries');
    assert.equal(saved.completed, false);
    assert.equal(new Date(saved.createdAt).toISOString(), saved.createdAt);
    assert.ok(Date.parse(saved.createdAt) >= before && Date.parse(saved.createdAt) <= Date.now());
  });

  it('auto-increments ids and keeps earlier todos', () => {
    cli('add', 'First');
    cli('add', 'Second');
    assert.equal(cli('add', 'Third').stdout, 'Added todo #3: Third\n');
    assert.deepEqual(readTodos().map((t) => [t.id, t.text]), [[1, 'First'], [2, 'Second'], [3, 'Third']]);
  });

  it('does not reuse the id of a deleted todo while a higher id exists', () => {
    cli('add', 'One');
    cli('add', 'Two');
    cli('add', 'Three');
    cli('delete', '2');
    assert.equal(cli('add', 'Four').stdout, 'Added todo #4: Four\n');
  });

  it('joins unquoted words into one todo', () => {
    cli('add', 'Walk', 'the', 'dog');
    assert.equal(readTodos()[0].text, 'Walk the dog');
  });

  it('keeps unicode text', () => {
    cli('add', 'Café ☕ 日本語 🍕');
    assert.equal(readTodos()[0].text, 'Café ☕ 日本語 🍕');
  });

  it('fails without text and does not create the data file', () => {
    assertFails(cli('add'), /Missing todo text\. Usage: node index\.js add/);
    assert.equal(fs.existsSync(file), false);
  });

  it('fails on whitespace-only text', () => {
    assertFails(cli('add', '   '), /Todo text cannot be empty/);
    assert.equal(fs.existsSync(file), false);
  });
});

describe('list', () => {
  it('reports an empty list when no data file exists', () => {
    const result = cli('list');
    assert.equal(result.code, 0);
    assert.match(result.stdout, /^No todos yet/);
    assert.equal(fs.existsSync(file), false, 'list must not create the data file');
  });

  it('reports an empty list after the last todo is deleted', () => {
    cli('add', 'Only');
    cli('delete', '1');
    assert.match(cli('list').stdout, /^No todos yet/);
  });

  it('shows id, [x] or [ ] and text for every todo', () => {
    cli('add', 'Buy groceries');
    cli('add', 'Walk the dog');
    cli('complete', '1');
    assert.deepEqual(cli('list'), {
      code: 0,
      stdout: '1. [x] Buy groceries\n2. [ ] Walk the dog\n',
      stderr: '',
    });
  });

  it('rejects extra arguments', () => {
    assertFails(cli('list', 'extra'), /takes no arguments/);
  });
});

describe('complete', () => {
  beforeEach(() => {
    cli('add', 'Buy groceries');
    cli('add', 'Walk the dog');
  });

  it('marks the todo as done and leaves others pending', () => {
    assert.deepEqual(cli('complete', '2'), { code: 0, stdout: 'Completed todo #2: Walk the dog\n', stderr: '' });
    assert.deepEqual(readTodos().map((t) => t.completed), [false, true]);
  });

  it('succeeds without rewriting the file when the todo is already done', () => {
    cli('complete', '1');
    const before = fs.readFileSync(file, 'utf8');
    const result = cli('complete', '1');
    assert.equal(result.code, 0);
    assert.equal(result.stdout, 'Todo #1 is already done: Buy groceries\n');
    assert.equal(fs.readFileSync(file, 'utf8'), before);
  });

  it('fails for an id that does not exist', () => {
    assertFails(cli('complete', '99'), /Todo #99 not found/);
  });

  it('fails without an id', () => {
    assertFails(cli('complete'), /Missing todo id\. Usage: node index\.js complete <id>/);
  });

  for (const id of ['abc', '0', '-1', '1.5']) {
    it(`fails for invalid id ${JSON.stringify(id)}`, () => {
      assertFails(cli('complete', id), /Invalid todo id/);
    });
  }

  it('fails when given more than one id', () => {
    assertFails(cli('complete', '1', '2'), /Expected exactly one todo id/);
    assert.deepEqual(readTodos().map((t) => t.completed), [false, false]);
  });
});

describe('delete', () => {
  beforeEach(() => {
    cli('add', 'Buy groceries');
    cli('add', 'Walk the dog');
  });

  it('removes the todo and keeps the rest', () => {
    assert.deepEqual(cli('delete', '1'), { code: 0, stdout: 'Deleted todo #1: Buy groceries\n', stderr: '' });
    assert.deepEqual(readTodos().map((t) => t.id), [2]);
  });

  it('fails for an id that does not exist and leaves the file unchanged', () => {
    const before = fs.readFileSync(file, 'utf8');
    assertFails(cli('delete', '3'), /Todo #3 not found/);
    assert.equal(fs.readFileSync(file, 'utf8'), before);
  });

  it('fails when deleting the same id twice', () => {
    cli('delete', '1');
    assertFails(cli('delete', '1'), /Todo #1 not found/);
  });

  it('fails without an id', () => {
    assertFails(cli('delete'), /Missing todo id\. Usage: node index\.js delete <id>/);
  });

  it('fails for an invalid id', () => {
    assertFails(cli('delete', 'first'), /Invalid todo id "first"/);
  });

  it('fails when given more than one id', () => {
    assertFails(cli('delete', '1', '2'), /Expected exactly one todo id/);
    assert.equal(readTodos().length, 2);
  });
});

describe('corrupted data file', () => {
  const CORRUPT = '{ not json';

  for (const argv of [['list'], ['add', 'New'], ['complete', '1'], ['delete', '1']]) {
    it(`${argv[0]} reports the problem and leaves the file untouched`, () => {
      fs.writeFileSync(file, CORRUPT);
      assertFails(cli(...argv), /todos\.json is corrupted: invalid JSON/);
      assert.equal(fs.readFileSync(file, 'utf8'), CORRUPT);
    });
  }

  it('reports invalid arguments before reading the file', () => {
    fs.writeFileSync(file, CORRUPT);
    assertFails(cli('add', '   '), /Todo text cannot be empty/);
    assertFails(cli('complete', 'abc'), /Invalid todo id/);
  });

  it('reports a structurally invalid todo', () => {
    fs.writeFileSync(file, JSON.stringify([{ id: 1, text: 'x', completed: 'no', createdAt: '2026-01-01T00:00:00.000Z' }]));
    assertFails(cli('list'), /todo at index 0 has an invalid "completed"/);
  });
});

describe('command dispatch', () => {
  it('prints usage to stderr and fails when no command is given', () => {
    const result = cli();
    assert.equal(result.code, 1);
    assert.match(result.stderr, /^Usage:/);
  });

  for (const flag of ['help', '--help', '-h']) {
    it(`prints usage to stdout for ${flag}`, () => {
      const result = cli(flag);
      assert.equal(result.code, 0);
      assert.match(result.stdout, /^Usage:[\s\S]*add[\s\S]*list[\s\S]*complete[\s\S]*delete/);
    });
  }

  // Object.prototype keys guard against a plain-object command table.
  for (const command of ['remove', 'LIST', 'constructor', '__proto__', 'toString']) {
    it(`rejects unknown command ${JSON.stringify(command)}`, () => {
      const result = cli(command);
      assert.equal(result.code, 1);
      assert.match(result.stderr, new RegExp(`Unknown command "${command}"`));
    });
  }
});

describe('end to end through node index.js', () => {
  function node(...argv) {
    const result = spawnSync(process.execPath, [ENTRY, ...argv], {
      cwd: dir,
      encoding: 'utf8',
      timeout: CHILD_TIMEOUT_MS,
    });
    return { code: result.status, stdout: result.stdout, stderr: result.stderr };
  }

  it('runs add, list, complete and delete against todos.json in the working directory', () => {
    assert.equal(node('add', 'Buy groceries').code, 0);
    assert.equal(node('add', 'Walk the dog').code, 0);
    assert.equal(node('complete', '1').code, 0);
    assert.equal(node('list').stdout, '1. [x] Buy groceries\n2. [ ] Walk the dog\n');
    assert.equal(node('delete', '2').code, 0);
    assert.equal(node('list').stdout, '1. [x] Buy groceries\n');
    assert.deepEqual(readTodos().map((t) => t.text), ['Buy groceries']);
  });

  it('exits with status 1 and writes errors to stderr', () => {
    const result = node('complete', '5');
    assert.equal(result.code, 1);
    assert.equal(result.stdout, '');
    assert.equal(result.stderr, 'Error: Todo #5 not found.\n');
  });

  // Concurrent processes can still lose each other's updates (no file lock),
  // but atomic writes must keep the file valid and the temp files distinct.
  it('leaves a valid data file and no temp files when adds run concurrently', async () => {
    const execFileAsync = promisify(execFile);
    const runs = Array.from({ length: CONCURRENT_RUNS }, (_, i) =>
      execFileAsync(process.execPath, [ENTRY, 'add', `Task ${i}`], { cwd: dir, timeout: CHILD_TIMEOUT_MS }));
    await Promise.all(runs);

    const todos = readTodos();
    assert.ok(todos.length >= 1 && todos.length <= CONCURRENT_RUNS);
    assert.deepEqual(fs.readdirSync(dir), ['todos.json']);
    assert.equal(node('list').code, 0);
  });
});
'use strict';

const { describe, it } = require('node:test');
const assert = require('node:assert/strict');
const {
  TodoError,
  parseId,
  parseText,
  addTodo,
  completeTodo,
  deleteTodo,
  formatList,
} = require('../lib/todos');

const NOW = new Date('2026-01-02T03:04:05.678Z');

function todo(id, overrides = {}) {
  return { id, text: `Todo ${id}`, completed: false, createdAt: NOW.toISOString(), ...overrides };
}

describe('parseId', () => {
  for (const [input, expected] of [['1', 1], ['42', 42], [' 7 ', 7], ['007', 7]]) {
    it(`accepts ${JSON.stringify(input)} as ${expected}`, () => {
      assert.equal(parseId(input), expected);
    });
  }

  const invalid = ['', '   ', 'abc', '0', '-1', '1.5', '1e3', '0x1', '12abc', 'Infinity', '١', '9007199254740993'];
  for (const input of invalid) {
    it(`rejects ${JSON.stringify(input)}`, () => {
      assert.throws(() => parseId(input), { name: 'TodoError', message: /Invalid todo id/ });
    });
  }
});

describe('parseText', () => {
  it('trims surrounding whitespace and keeps unicode text intact', () => {
    assert.equal(parseText('  Café ☕ 日本語 🍕  '), 'Café ☕ 日本語 🍕');
  });

